body.script:
var COUNTRIES = ["Afghanistan","Aland Islands","Albania","Algeria","American Samoa","Andorra","Angola","Anguilla","Antarctica","Antigua and Barbuda","Argentina","Armenia","Aruba","Australia","Austria","Azerbaijan","Bahamas","Bahrain","Bangladesh","Barbados","Belarus","Belgium","Belize","Benin","Bermuda","Bhutan","Bolivia","Bosnia and Herzegovina","Botswana","Brazil","Brunei","Bulgaria","Burkina Faso","Burundi","Cambodia","Cameroon","Canada","Cape Verde","Cayman Islands","Central African Republic","Chad","Chile","China","Colombia","Comoros","Congo","Costa Rica","Croatia","Cuba","Cyprus","Czech Republic","Denmark","Djibouti","Dominica","Dominican Republic","Ecuador","Egypt","El Salvador","Equatorial Guinea","Eritrea","Estonia","Ethiopia","Fiji","Finland","France","Gabon","Gambia","Georgia","Germany","Ghana","Greece","Grenada","Guatemala","Guinea","Guyana","Haiti","Honduras","Hungary","Iceland","India","Indonesia","Iran","Iraq","Ireland","Israel","Italy","Jamaica","Japan","Jordan","Kazakhstan","Kenya","Kuwait","Kyrgyzstan","Laos","Latvia","Lebanon","Lesotho","Liberia","Libya","Liechtenstein","Lithuania","Luxembourg","Madagascar","Malawi","Malaysia","Maldives","Mali","Malta","Mauritania","Mauritius","Mexico","Moldova","Monaco","Mongolia","Montenegro","Morocco","Mozambique","Myanmar","Namibia","Nepal","Netherlands","New Zealand","Nicaragua","Niger","Nigeria","North Korea","Norway","Oman","Pakistan","Panama","Papua New Guinea","Paraguay","Peru","Philippines","Poland","Portugal","Qatar","Romania","Russia","Rwanda","Saudi Arabia","Senegal","Serbia","Sierra Leone","Singapore","Slovakia","Slovenia","Somalia","South Africa","South Korea","South Sudan","Spain","Sri Lanka","Sudan","Sweden","Switzerland","Syria","Taiwan","Tajikistan","Tanzania","Thailand","Togo","Trinidad and Tobago","Tunisia","Turkey","Turkmenistan","Uganda","Ukraine","United Arab Emirates","United Kingdom","United States","Uruguay","Uzbekistan","Venezuela","Vietnam","Yemen","Zambia","Zimbabwe"];

function makeCountryDropdown(name, label, container) {
    var wrap = document.createElement('div');
    wrap.style.cssText = 'position:relative;margin-bottom:10px;max-width:600px';
    wrap.innerHTML = '<div style="display:flex;align-items:center;border:1px solid #e0e0e0;border-radius:8px;padding:10px 16px;background:#fff">' +
        '<div style="flex:1;cursor:pointer;font-size:14px;color:#888" id="lbl_'+name+'" onclick="toggleDrop(\'drop_'+name+'\')">' + label + '</div>' +
        '<button type="button" style="width:24px;height:24px;border-radius:50%;background:#1a2340;border:none;cursor:pointer;color:#fff;font-size:12px" onclick="clearDrop(\''+name+'\')">&#x2715;</button>' +
        '</div>' +
        '<input type="hidden" name="'+name+'" id="val_'+name+'"/>' +
        '<div id="drop_'+name+'" style="display:none;position:absolute;z-index:200;width:100%;background:#fff;border:1px solid #ddd;border-radius:4px;max-height:200px;overflow:hidden">' +
        '<input type="text" placeholder="Search..." oninput="filterDrop(this,\'list_'+name+'\')" style="width:100%;padding:8px 12px;border:none;border-bottom:1px solid #eee;outline:none;font-size:13px"/>' +
        '<div id="list_'+name+'" style="max-height:160px;overflow-y:auto"></div></div>';
    container.appendChild(wrap);
    var list = document.getElementById('list_'+name);
    COUNTRIES.forEach(function(c){
        var d = document.createElement('div');
        d.textContent = c;
        d.style.cssText = 'padding:8px 12px;font-size:13px;cursor:pointer';
        d.onmouseover = function(){this.style.background='#e8f8f5'};
        d.onmouseout = function(){this.style.background=''};
        d.onclick = function(){
            document.getElementById('val_'+name).value = c;
            document.getElementById('lbl_'+name).textContent = c;
            document.getElementById('lbl_'+name).style.color = '#333';
            document.getElementById('drop_'+name).style.display = 'none';
        };
        list.appendChild(d);
    });
}

function toggleDrop(id){
    var d = document.getElementById(id);
    d.style.display = d.style.display === 'none' ? 'block' : 'none';
}

function filterDrop(input, listId){
    var q = input.value.toLowerCase();
    document.getElementById(listId).querySelectorAll('div').forEach(function(d){
        d.style.display = d.textContent.toLowerCase().includes(q) ? '' : 'none';
    });
}

function clearDrop(name){
    document.getElementById('val_'+name).value = '';
    document.getElementById('lbl_'+name).textContent = name.replace(/_/g,' ');
    document.getElementById('lbl_'+name).style.color = '#888';
}

function updateMarkets(type, count){
    var container = document.getElementById(type+'_dropdowns');
    container.innerHTML = '';
    count = parseInt(count) || 0;
    for(var i=1; i<=count; i++){
        makeCountryDropdown(type+'_market_'+i, type.charAt(0).toUpperCase()+type.slice(1)+' market '+i, container);
    }
}

function clearMarkets(type){
    document.getElementById(type+'Count').value = '';
    document.getElementById(type+'_dropdowns').innerHTML = '';
}

function togglePaidCapital(val){
    document.getElementById('capital_range_div').classList.toggle('hidden', val !== 'yes');
}

function toggleWebsite(val){
    document.getElementById('website_url_div').classList.toggle('hidden', val !== 'yes');
}

document.addEventListener('click', function(e){
    document.querySelectorAll('[id^="drop_"]').forEach(function(d){
        if(!d.parentElement.contains(e.target)) d.style.display='none';
    });
});
